# 182 daily topics (26 weeks) for the Faith Forward social campaign,
# Sunday Nov 1, 2026 through Saturday May 1, 2027.
# Each day: (pillar, title, hook, message, call_to_action, [topic hashtags])
# Pillars: mission, k9, faith, resource, donate, volunteer, mental, partner, story

WEEKS = [
("Launch: Who We Are", ["FaithForwardLaunch"], [
 ("mission", "Faith Forward Is Here", "Today we launch a mission born on the streets of St. Louis.", "Faith Forward Foundation serves displaced and homeless veterans, their families, and the dogs who walk beside them, with supplies, resources, and faith-based care. Founded on All Saints' Day by a three-tour Iraq veteran and ordained minister.", "Follow along and share with one veteran you know.", ["AllSaintsDay", "NewMinistry", "VeteranOutreach"]),
 ("story", "Our Founder's Story", "He walked these streets with nothing but a backpack and a dog.", "The Reverend Paul Moore served three combat tours in Iraq, came home disabled, and fought through homelessness, addiction, and incarceration. Grace found him. Now he goes back to find others.", "Read the full story on our website.", ["FounderStory", "Redemption", "IraqVeteran"]),
 ("faith", "Spiritus Invictus", "What does the Latin on our crest mean?", "Spiritus Invictus means 'the unconquered spirit.' The shield is the armor of God, the gold cross is Christ at the center, and the flame is the Holy Spirit and the fire war could not put out.", "Comment 🔥 if your spirit is still unconquered.", ["SpiritusInvictus", "ArmorOfGod", "CrestMeaning"]),
 ("k9", "Why Dogs?", "Most unhoused veterans have a dog. Here's why that matters.", "A dog is warmth on a freezing night, security at 3 a.m., and a reason to get up. Too many shelters force veterans to choose between a bed and their dog. We refuse to make anyone choose.", "Share if you believe no veteran should have to choose.", ["VeteransAndDogs", "NoDogLeftBehind", "PetFriendlyHousing"]),
 ("donate", "Six Things We Need", "Six donations that change a veteran's week.", "Backpacks, clothing for men and women, hygiene supplies, non-perishable food, animal supplies and toys, and religious reading and prayer items. Every item is blessed by a local priest before it goes out.", "See the full list at the link in our bio.", ["DonationDrive", "BlessedGifts", "HelpVeterans"]),
 ("partner", "STL Veterans Hub", "Every veteran resource in St. Louis, on one map.", "Faith Forward is closely associated with STL Veterans Hub (stlveteranshub.com), also founded by Rev. Paul Moore. The Hub maps the resources; Faith Forward walks veterans to them.", "Bookmark stlveteranshub.com.", ["STLVeteransHub", "VeteranResources", "StLouisMO"]),
 ("faith", "Saturday Prayer", "A prayer for every veteran sleeping outside tonight.", "Lord, cover every veteran sleeping outside tonight. Keep them warm, keep their dogs close, and send someone, send us, to remind them they are not forgotten. Amen.", "Type 'Amen' and pray with us.", ["PrayerForVeterans", "SaturdayPrayer", "PrayWithUs"]),
]),
("Veterans Day & St. Martin", ["VeteransDay"], [
 ("faith", "The Soldier Who Shared His Cloak", "A Roman soldier cut his cloak in half for a freezing beggar.", "St. Martin of Tours saw a man everyone else walked past and shared what he had. His feast day is November 11, the same day as Veterans Day. His example is our mission.", "Who will you share your cloak with this week?", ["StMartinOfTours", "SoldierSaint", "ShareYourCloak"]),
 ("donate", "Winter Backpack Drive Kicks Off", "Socks are the #1 thing veterans on the street ask for.", "Our Winter Survival Backpack Drive is live: wool socks, thermal layers, hats, gloves, hand warmers, hygiene kits, and dog coats. Each pack is blessed before distribution.", "Drop off a backpack or schedule a pickup through our website.", ["WinterBackpackDrive", "SocksForVets", "ColdWeatherOutreach"]),
 ("story", "Thank You Isn't Enough", "Saying 'thank you for your service' is a start.", "The best way to honor veterans is to make sure none of them freeze, starve, or die alone. This Veterans Day, pair your thank-you with action.", "Tag a veteran and tell them what their service means to you.", ["ThankAVeteran", "HonorVeterans", "BeyondThankYou"]),
 ("mission", "Happy Veterans Day", "To every veteran: you are seen, valued, and not forgotten.", "Today we pray, then we take blessed backpacks to the street. On the feast of St. Martin, we honor all who served by serving the ones still fighting.", "Join us in prayer for veterans today.", ["HappyVeteransDay", "November11", "StLouisVeterans"]),
 ("mental", "Veterans Day Can Hurt", "For some veterans, Veterans Day is the hardest day of the year.", "Memories of buddies who didn't come home, isolation, and survivor's guilt can hit hard. If that's you, you're not alone. Call 988 and press 1, any time.", "Save 988 in your phone today.", ["988Press1", "VeteranMentalHealth", "YouAreNotAlone"]),
 ("k9", "Cold Paws, Warm Hearts", "Your dog's paws need winter protection too.", "Wipe paws after walks to remove de-icer salt, check for ice between toes, and put a coat on short-coated dogs below 40°F. For outdoor shelters, use straw, not blankets.", "Donate a dog coat to a veteran's pup.", ["WinterDogCare", "PawProtection", "DogCoatDrive"]),
 ("faith", "Saturday Prayer: For the Fallen", "Eternal rest grant unto them, O Lord.", "We remember every service member who did not come home, and every veteran lost after coming home. Let perpetual light shine upon them, and comfort their families.", "Share the name of someone you remember.", ["ForTheFallen", "Remember", "EternalRest"]),
]),
("The Dog at His Side", ["K9Program"], [
 ("k9", "Introducing the K9 Program", "A first-of-its-kind faith-based K9 program for veterans.", "We feed, heal, and train both ends of the leash: food, vet care, obedience, emotional-support and service-task training, and a blessing for every dog.", "Learn about the program on our website.", ["FaithBasedK9", "VeteranK9", "DogTraining"]),
 ("k9", "The Impossible Choice", "A bed or your dog. Which would you choose?", "Many veterans turn down shelter rather than abandon the dog that kept them alive. Healthy, trained, documented dogs open more doors to housing.", "Share to help change shelter and housing pet policies.", ["PetInclusiveHousing", "ImpossibleChoice", "KeepThemTogether"]),
 ("k9", "Muzzle Training Is Love", "A muzzle isn't a punishment. It's a passport.", "A dog that happily wears a basket muzzle can be safely examined, transported, and welcomed into more places. Start with peanut butter (xylitol-free!) inside the basket.", "Watch our muzzle-training basics in the K9 Suite.", ["MuzzleTraining", "MuzzleUp", "ResponsibleOwnership"]),
 ("donate", "Fill a Dog Bowl", "$1 = about a day of food for a veteran's dog.", "Sealed bags of dog food, pop-top canned food, leashes, harnesses, coats, bowls, and flea/tick prevention keep veterans' dogs healthy and housing-ready.", "Drop off animal supplies at any Faith Forward drive.", ["DogFoodDrive", "FeedTheDogs", "AnimalSupplies"]),
 ("story", "Loyalty Is a Military Value", "They aren't 'service-resistant.' They're loyal.", "Veterans learned never to leave a buddy behind. Many apply that to their dog. We honor that loyalty by keeping them together.", "Comment with your dog's name. We'll pray for them.", ["Loyalty", "NeverLeaveABuddy", "DogsOfFaithForward"]),
 ("k9", "Read Your Dog", "Your dog is talking. Are you listening?", "Lip licks, yawns, turning away, and a stiff body are early stress signals. Catch them early and you prevent most problems. It's Lesson 1 of our handler course.", "Try narrating your dog's body language on your next walk.", ["DogBodyLanguage", "CalmingSignals", "HandlerTraining"]),
 ("faith", "Saturday Prayer: For Our Animals", "A righteous man regardeth the life of his beast. (Proverbs 12:10)", "Creator of all living things, bless the dogs who keep our veterans warm, alert, and loved. Open the doors of shelters and homes to both. Amen.", "Pray this over your pet tonight.", ["PrayerForPets", "Proverbs1210", "CreationCare"]),
]),
("Gratitude & Thanksgiving", ["Thanksgiving"], [
 ("faith", "In Every Thing Give Thanks", "Not FOR every thing. IN every thing.", "Paul wrote 1 Thessalonians 5:18 from a life of shipwrecks and prison. Gratitude isn't denial; it's a discipline that fights despair.", "Name one thing you're thankful for in the comments.", ["GiveThanks", "Gratitude", "1Thessalonians518"]),
 ("mental", "The Three Good Things Drill", "A 2-minute nightly drill that fights despair.", "Every night, write three things that went right, why they happened, and thank God for each. Small counts: hot coffee, a warm dog, someone saying your name.", "Try it tonight and tell us how it went.", ["GratitudePractice", "MentalHealthTools", "ThreeGoodThings"]),
 ("donate", "Set One Extra Place", "Who isn't at a table this Thanksgiving?", "Invite a veteran who'd otherwise be alone. Can't host? Deliver a plate. Can't deliver? Donate non-perishable food or a grocery card.", "Tag someone who always makes room at the table.", ["ExtraPlace", "ThanksgivingOutreach", "NoOneAlone"]),
 ("k9", "Thanksgiving Dog Safety", "Keep these off your dog's plate this Thanksgiving.", "No cooked bones, onions, garlic, grapes, raisins, chocolate, xylitol, or fatty scraps. A spoonful of plain turkey breast or plain pumpkin is a safe treat.", "Share with every dog owner hosting this week.", ["ThanksgivingPetSafety", "DogSafety", "ToxicFoods"]),
 ("mission", "Happy Thanksgiving", "We're thankful for you.", "To every donor, volunteer, partner, priest, prayer warrior, and veteran who trusts us with their story: thank you. You are the reason Faith Forward exists.", "Happy Thanksgiving from all of us.", ["HappyThanksgiving", "ThankYou", "FaithForwardFamily"]),
 ("volunteer", "Serve the Weekend", "Holiday weekends are lonely weekends on the street.", "Our teams go out this weekend with food, warm clothes, and dog supplies. Join an orientation and serve with us.", "Sign up on our Contact page.", ["VolunteerStLouis", "HolidayOutreach", "ServeTogether"]),
 ("faith", "Saturday Prayer: Gratitude", "Thank You, Lord, for the breath in our lungs.", "Thank You for the food in our bowl, the roof we may or may not have, the dog at our feet, and the people who didn't give up on us. Teach us gratitude in every circumstance. Amen.", "Pray this with your family tonight.", ["GratefulHeart", "PrayerOfThanks", "WeekendPrayer"]),
]),
("Advent & Giving Tuesday", ["Advent"], [
 ("faith", "Advent Begins", "One candle against the longest nights of the year.", "Advent is four weeks of waiting in the dark for the Light. Veterans know waiting: for claims, housing, appointments, healing. Something is coming.", "Light a candle tonight and pray for a veteran who is waiting.", ["AdventSeason", "WaitingInHope", "Isaiah92"]),
 ("story", "The Holy Family Was Displaced", "Christ was born to a family with no room at the inn.", "Then they fled to Egypt as refugees. Every veteran sleeping in a car tonight is in the company of the Holy Family.", "Share this to help someone see the homeless differently.", ["HolyFamily", "NoRoomAtTheInn", "Displaced"]),
 ("donate", "Giving Tuesday", "Today, your gift is a blessed backpack on a veteran's back.", "This Giving Tuesday, help us fill backpacks with socks, hats, gloves, hygiene kits, food, and dog coats for St. Louis veterans living outside.", "Give or host a drive. Link in bio.", ["GivingTuesday", "GiveHope", "BackpacksForVets"]),
 ("resource", "HUD-VASH Explained", "How do homeless veterans actually get housed?", "HUD-VASH pairs a HUD housing voucher with VA case management. Ask any VA homeless program or call 877-424-3838 to start.", "Save this and share with a veteran who needs it.", ["HUDVASH", "VeteranHousing", "EndVeteranHomelessness"]),
 ("k9", "Teach a Settle", "Calm is a skill, and you can teach it.", "Put a mat down and reward your dog every time they lie down and relax on it. A dog that can settle anywhere is welcomed in more places.", "Try it for 5 minutes today.", ["SettleTraining", "CalmDog", "PlaceCommand"]),
 ("mental", "Waiting Is Hard", "If you're waiting on something big, read this.", "Waiting doesn't have to be passive. Pray, do the next right thing, and let someone wait with you. Faith Forward can help track claims and housing applications.", "Message us if you need a battle buddy for the wait.", ["WaitingWell", "VeteranSupport", "OneStepAtATime"]),
 ("faith", "Saturday Prayer: O Come Emmanuel", "Come, Lord Jesus.", "Lord, You were born homeless so no homeless person would be outside Your love. Shine Your light on every veteran waiting in the dark. Come quickly. Amen.", "Pray 'Come, Lord Jesus' with us.", ["OComeEmmanuel", "AdventPrayer", "Maranatha"]),
]),
("Winter Survival", ["WinterSurvival"], [
 ("resource", "Know the Signs of Hypothermia", "Shivering that STOPS is a warning sign.", "Hypothermia signs: shivering that stops, confusion, slurred speech, clumsiness, drowsiness. Frostbite: white or grayish skin, numbness. Call 911. Don't rub frostbite.", "Save this. It could save a life.", ["Hypothermia", "ColdWeatherSafety", "WinterSafety"]),
 ("donate", "What Actually Helps in Winter", "The items veterans on the street ask for most.", "Wool socks, hats, gloves, hand and foot warmers, mylar blankets, waterproof backpacks, high-calorie food, lip balm, and dog coats and straw for their pups.", "Pack one kit this week.", ["WinterKit", "WhatToDonate", "HelpTheHomeless"]),
 ("volunteer", "Pack a Car Kit", "Keep a blessing kit in your car.", "Socks, hat, gloves, hand warmers, a protein bar, and a resource card. When you see someone in need, you're ready.", "Show us your car kit in the comments.", ["CarKit", "BlessingBags", "BeReady"]),
 ("k9", "Straw, Not Blankets", "Blankets can freeze. Here's what works for outdoor dogs.", "Blankets soak up moisture and freeze. Straw stays dry and insulates. Raise beds off the ground and block the wind. Short-coated dogs need coats below 40°F.", "Donate a bale of straw or a dog coat this winter.", ["OutdoorDogs", "WinterDogShelter", "DogCare"]),
 ("resource", "Warming Centers", "Know where the warming centers are BEFORE the freeze.", "When temperatures drop, St. Louis opens warming centers and overflow shelters. Call 211 for locations. Ask about pets, and call Faith Forward if they're not allowed.", "Share so someone knows where to go tonight.", ["WarmingCenters", "Call211", "StLouisWinter"]),
 ("story", "A Blessed Backpack", "Why does a priest bless every backpack?", "Because every veteran who receives one should know that someone prayed for them by name. The blessing turns supplies into a message: you are not forgotten.", "Tag your parish and invite them to host a drive.", ["BlessedBackpacks", "PrayedFor", "ParishOutreach"]),
 ("faith", "Saturday Prayer: In Winter", "Lord, it is cold tonight.", "Cover every veteran sleeping outside. Lead them to warmth, keep their feet dry and their dogs warm beside them. Let no one freeze alone in the dark. Amen.", "Pray this every cold night this winter.", ["WinterPrayer", "PrayForTheHomeless", "ColdNights"]),
]),
("Invisible Wounds", ["InvisibleWounds"], [
 ("mental", "What Is Moral Injury?", "Not all wounds are visible. Some are moral.", "Moral injury comes from doing, failing to prevent, or witnessing something that violates your deepest sense of right and wrong, or from betrayal by people you trusted. It's real, and it can heal.", "Read our full article on moral injury.", ["MoralInjury", "VeteranMentalHealth", "HiddenWounds"]),
 ("faith", "You Are Not Beyond Grace", "David. Peter. Paul. None were beyond grace.", "David wrote Psalm 51 after his worst sin. Peter was restored after denying Christ three times. If grace reached them, it can reach you.", "Comment 'Psalm 51' if you need this today.", ["Grace", "Psalm51", "Restoration"]),
 ("mental", "Holidays and Grief", "The holidays can magnify what's missing.", "Empty chairs, lost marriages, buddies who didn't come home. Plan your holidays, keep your battle buddy close, and remember 988, press 1, is always open.", "Check on someone who's grieving this season.", ["HolidayGrief", "CheckOnYourBuddies", "988"]),
 ("resource", "VA Chaplains", "Did you know every VA has chaplains?", "VA chaplains are trained in spiritual care for veterans, including moral injury. Ask for one at any VA visit, regardless of your faith.", "Share with a veteran who carries something heavy.", ["VAChaplain", "SpiritualCare", "VeteranResources"]),
 ("k9", "Deep Pressure Therapy", "Why a dog's weight on your lap can calm a panic attack.", "Deep pressure therapy (DPT) is a trained task where the dog lies across the handler's lap or chest. The steady weight helps the nervous system settle.", "See the DPT training steps in our K9 Suite.", ["DeepPressureTherapy", "PsychiatricServiceDog", "PTSDDog"]),
 ("partner", "Faith + Clinical Care", "Faith and therapy aren't enemies.", "Faith Forward offers spiritual care and warm handoffs. Our clinical partners offer evidence-based treatment. Together, they work best.", "Mental-health providers: partner with us.", ["FaithAndTherapy", "MentalHealthPartners", "WarmHandoff"]),
 ("faith", "Saturday Prayer: Mercy", "Wash me whiter than snow.", "Merciful God, You see what we did and what we couldn't stop. We lay it at the foot of the Cross. Forgive us, help us forgive, and make us whole. Amen.", "Pray this when the memories come.", ["PrayerForHealing", "Mercy", "Isaiah118"]),
]),
("Christmas", ["Christmas"], [
 ("faith", "No Room", "Two words in the Christmas story we read past: no room.", "The Son of God was born where the animals slept because there was no room. The question of Christmas: where will I make room?", "Make room for one this week.", ["NoRoom", "Luke27", "MakeRoom"]),
 ("donate", "Christmas for Veterans", "Socks, coats, gifts for kids, and treats for dogs.", "This week we distribute warm clothing, hygiene, food, gifts for veteran families, and toys and treats for their animals. Every item is blessed.", "There's still time to give. Link in bio.", ["ChristmasGiving", "VeteranFamilies", "GiftsForVets"]),
 ("k9", "Holiday Hazards for Dogs", "Five Christmas hazards for dogs.", "Chocolate, xylitol in sugar-free candy, tinsel and ribbon, lilies, and electrical cords. Keep food gifts off the floor. A frozen stuffed Kong keeps dogs busy during parties.", "Share with your dog-owning friends.", ["ChristmasPetSafety", "HolidayDogs", "PetSafetyTips"]),
 ("story", "The Animals at the Manger", "The first to keep the newborn King warm were animals.", "Tradition places an ox and a donkey at the manger. The animals beside our veterans keep them warm too. That's why our ministry includes them.", "Bring a treat to a veteran's dog this week.", ["Manger", "AnimalsOfChristmas", "VeteransDogs"]),
 ("faith", "Christmas Eve", "For unto you is born this day a Saviour. (Luke 2:11)", "Tonight we pray for every veteran far from home, every family apart, and every soul who feels shut out. Fear not: good tidings of great joy are for you.", "Merry Christmas Eve. Tell us where you're worshiping tonight.", ["ChristmasEve", "Luke211", "GoodTidings"]),
 ("mission", "Merry Christmas", "The Word was made flesh and dwelt among us.", "Merry Christmas from Faith Forward. God came close, into the cold, into poverty, into a displaced family. He's still coming close to the forgotten.", "Merry Christmas! 🎄✝️", ["MerryChristmas", "Emmanuel", "GodWithUs"]),
 ("mental", "After Christmas", "The days after Christmas can feel heavy.", "When the visits end and the lights come down, loneliness can creep in. Check on the veterans and seniors in your life this week.", "Text one person today: 'Thinking of you.'", ["AfterChristmas", "CheckIn", "Loneliness"]),
]),
("New Year Battle Plan", ["NewYear"], [
 ("mission", "A Battle Plan, Not a Resolution", "Resolutions are wishes. Veterans make plans.", "Write a one-sentence mission for the year, your commander's intent (the why), phase lines with dates, resources, a battle buddy, and a weekly after-action review.", "Write your mission in the comments.", ["BattlePlan", "NewYearGoals", "VeteranMindset"]),
 ("faith", "Behold, I Will Do a New Thing", "Remember ye not the former things. (Isaiah 43:18-19)", "God's mercies are new every morning. A new year is good, but so is a new day. You can start over at any minute.", "Share with someone who needs a fresh start.", ["NewThing", "Isaiah43", "FreshStart"]),
 ("resource", "Free VA Claim Help", "Never pay anyone to file your initial VA claim.", "Accredited Veterans Service Officers (Missouri Veterans Commission, DAV, VFW, American Legion) help you file for free.", "Save this. Share with a veteran who's thinking about filing.", ["VAClaim", "VSO", "FreeHelp"]),
 ("k9", "New Year, New Skill: Place", "The most underrated command in dog training.", "Lure your dog onto a raised cot, reward all four paws on, then reward lying down. Build to 30 minutes. Place is your dog's off switch.", "Show us your dog's place in the comments!", ["PlaceCommand", "DogTrainingTips", "NewSkill"]),
 ("volunteer", "Serve in the New Year", "Make serving veterans part of your year.", "Outreach, sorting and packing, driving, prayer team, K9 handling, events, and professional skills. There's a place for you.", "Sign up for a January orientation.", ["VolunteerGoals", "ServeInTheNewYear", "StLouisVolunteers"]),
 ("mental", "One Battle Buddy", "No one goes outside the wire alone.", "Pick one person who will check on you every week this year. If you don't have one, Faith Forward volunteers can be that person.", "Tag your battle buddy.", ["BattleBuddy", "Accountability", "NoOneAlone"]),
 ("faith", "Saturday Prayer: New Year", "Lord, I hand You this year.", "Forgive yesterday, guide today, hold tomorrow. Give me one mission worth fighting for and the humility to ask for help. Be my Commander. Amen.", "Pray this to start your year.", ["NewYearPrayer", "Surrender", "Commander"]),
]),
("Meet Gypse", ["MeetGypse"], [
 ("k9", "Meet Gypse", "Meet the blue nose pit bull leading our K9 program.", "Gypse is a 2-year-old female blue nose pit bull and the founding dog of the Faith Forward K9 Program. She's training with our founder through every phase.", "Say hi to Gypse in the comments! 💙", ["BlueNosePitBull", "PitBullsOfInstagram", "K9Program"]),
 ("story", "Why the Founder Trains First", "He won't ask anyone to do what he hasn't done.", "Rev. Paul Moore is completing every lesson with Gypse before certifying a single trainer. Leaders go first.", "Follow Gypse's training journey.", ["ServantLeadership", "LeadersGoFirst", "TrainTheTrainer"]),
 ("k9", "What Is a Blue Nose?", "Is a blue nose pit bull a separate breed?", "No. Blue nose is a color variety of the American Pit Bull Terrier and related breeds, caused by a dilute gene. Blue dogs can have sensitive skin, so they need good nutrition and gentle care.", "Share with a pit bull lover.", ["BlueNose", "PitBullFacts", "DogGenetics"]),
 ("k9", "Pit Bull Myths", "Three things people get wrong about pit bulls.", "Most are deeply people-oriented. Many become dog-selective as adults, so management matters. And they make outstanding emotional-support dogs thanks to their love of contact.", "Drop a 💙 if you love a pit bull.", ["PitBullMyths", "EndBSL", "BullyBreeds"]),
 ("k9", "Gypse's First Lesson", "Every great dog starts with one second of eye contact.", "Say the name once. The instant she looks, mark 'YES' and reward. Ten reps, twice a day. Name recognition is the foundation for everything.", "Try it with your dog today.", ["NameGame", "DogTrainingBasics", "MarkerTraining"]),
 ("donate", "Sponsor a Dog", "Feed a veteran's dog for a month.", "A 30-lb bag of quality kibble feeds a 50-lb dog about a month. Donate sealed bags or pop-top cans at any Faith Forward drive.", "Sponsor a month of food. Link in bio.", ["SponsorADog", "DogFoodDonation", "FeedAVeteransDog"]),
 ("faith", "Saturday Prayer: Handlers", "Make me a calm leader for the dog in my care.", "Lord, let my hands be gentle, my voice steady, my commands clear. Teach me to read what she can't say. Let us be a team that brings peace. Amen.", "Pray this before your next training session.", ["HandlersPrayer", "DogTrainers", "Stewardship"]),
]),
("Understanding PTSD", ["PTSDAwareness"], [
 ("mental", "PTSD Is Not Weakness", "PTSD is a treatable condition, not a character flaw.", "PTSD can follow trauma like combat, assault, or disaster. It changes how the brain processes threat. Willpower alone won't fix it, but treatment works.", "Share to fight the stigma.", ["PTSDIsReal", "EndTheStigma", "MentalHealthMatters"]),
 ("mental", "Four Signs of PTSD", "The four symptom groups of PTSD.", "Re-experiencing (nightmares, flashbacks), avoidance, negative changes in mood and thinking, and hyperarousal (on edge, poor sleep, easily startled).", "Save this for someone you love.", ["PTSDSigns", "KnowTheSigns", "VeteranMentalHealth"]),
 ("resource", "PTSD Help in St. Louis", "Where to get PTSD treatment in St. Louis.", "VA St. Louis PTSD programs (314-652-4100), the St. Louis Vet Center (314-845-8580), and Coaching Into Care for families (888-823-7458).", "Save and share.", ["PTSDTreatment", "StLouisVA", "VetCenter"]),
 ("faith", "He Healeth the Broken in Heart", "Psalm 147:3 is a promise.", "He heals the brokenhearted and binds up their wounds. God works through prayer and through doctors and counselors. Luke was a physician.", "Comment 'Psalm 147' if you're believing for healing.", ["Psalm1473", "Healing", "BrokenHearted"]),
 ("partner", "Churches Can Help", "Five ways your church can welcome veterans with PTSD.", "Seat options near exits, warnings before loud moments, trained greeters, veterans fellowships, and partnering with ministries like Faith Forward.", "Tag your pastor.", ["ChurchMinistry", "VeteransMinistry", "WelcomeVeterans"]),
 ("k9", "Nightmare Interruption", "Some service dogs are trained to wake veterans from nightmares.", "The dog learns to respond to thrashing or distressed sounds by nudging, licking, or pawing the handler awake, then turning on a light.", "Learn the steps in our K9 Suite Phase 3.", ["ServiceDogTasks", "PTSDServiceDog", "Nightmares"]),
 ("faith", "Saturday Prayer: Against the Night", "Lord Jesus, stand watch over me tonight.", "When the memories come at night, quiet the noise in my head. Replace fear with Your peace. When I can't sleep, let me rest in You. Amen.", "Share with a veteran who struggles to sleep.", ["NightPrayer", "PeaceAtNight", "Psalm48"]),
]),
("Brotherhood", ["Brotherhood"], [
 ("mental", "Isolation Is the Enemy", "The enemy wants you alone.", "Loneliness is linked to depression, substance misuse, and suicide. Veterans who isolate stop asking for help. Rebuild your unit.", "Call one person from your old unit this week.", ["Isolation", "ReachOut", "VeteranCommunity"]),
 ("story", "MLK Day of Service", "Life's most persistent and urgent question: what are you doing for others?", "On Martin Luther King Jr. Day, we serve. Join an outreach, donate, or check on a neighbor.", "Share how you're serving today.", ["MLKDay", "DayOfService", "ServeOthers"]),
 ("faith", "Two Are Better Than One", "Woe to him that is alone when he falleth.", "Ecclesiastes 4:9-10 understood what every squad knows: you need someone to pick you up.", "Tag the person who picks you up.", ["Ecclesiastes4", "BrotherhoodAndSisterhood", "PickEachOtherUp"]),
 ("resource", "Veteran Groups in St. Louis", "Where to find your new unit.", "VFW, American Legion, DAV, Team Rubicon, The Mission Continues, and Faith Forward fellowships. Find people who get it.", "Comment with your favorite veteran group.", ["VeteranGroups", "TeamRubicon", "TheMissionContinues"]),
 ("k9", "A Dog Is a Social Bridge", "Walking your dog gets you talking to strangers.", "A well-mannered dog makes it easy for neighbors to say hello. Practice loose-leash walking: stop when the leash tightens, go when it loosens.", "Try 'be a tree' on your next walk.", ["LooseLeashWalking", "DogWalk", "Connection"]),
 ("volunteer", "Serving Builds Brotherhood", "Missing the mission? Serve.", "Volunteering restores teamwork and purpose. Veterans make outstanding outreach team members because they understand the people we serve.", "Veterans: join an outreach team.", ["VeteransServing", "Purpose", "Mission"]),
 ("faith", "Saturday Prayer: Brotherhood", "Thank You for my battle buddies.", "Keep us faithful to one another. Let us check on each other, pick up the phone, and never let one of us fight alone. Amen.", "Tag a battle buddy and pray for them.", ["BattleBuddyPrayer", "Faithful", "NeverAlone"]),
]),
("Everyone Counts", ["EveryoneCounts"], [
 ("resource", "The Point-in-Time Count", "Why do communities count the homeless every January?", "The PIT Count is a one-night snapshot that shapes funding and services. If someone isn't counted, they're harder to help.", "Volunteer for this year's count.", ["PITCount", "HomelessnessData", "Volunteer"]),
 ("faith", "The Shepherd Counts", "He left the 99 to find the 1.", "God knows every name. Counting each person is a small echo of that divine attention: every person matters enough to be counted.", "Share Luke 15:4 with someone who feels lost.", ["Luke154", "GoodShepherd", "TheOne"]),
 ("resource", "One Question That Opens Doors", "'Have you ever served in the military?'", "Some veterans don't identify as veterans. Asking this gently can connect them to VA homeless programs and benefits.", "Save this question for your next outreach.", ["AskTheQuestion", "VeteranIdentification", "OutreachTips"]),
 ("volunteer", "What to Expect on Outreach", "Your first outreach, step by step.", "Orientation, prayer, teams of two, a full kit, respectful introductions, asking before approaching dogs, and a debrief.", "Sign up for orientation.", ["FirstOutreach", "StreetMinistry", "HowToHelp"]),
 ("k9", "Approaching a Stranger's Dog", "The right way to approach someone's dog on outreach.", "Ask the owner first. Approach from the side, crouch, let the dog come to you, and offer water. Watch for stiffness or hard staring.", "Share with every volunteer you know.", ["DogSafety", "OutreachSafety", "AskFirst"]),
 ("donate", "Count Night Kits", "Every veteran counted gets something tangible.", "We bring backpacks, socks, food, and dog supplies on count night. Help us stock up.", "Donate supplies this week.", ["CountNight", "OutreachKits", "GiveWarmth"]),
 ("faith", "Saturday Prayer: The Lost", "Good Shepherd, You know every name.", "As we count, let us see each person as You see them: beloved, valuable, worth finding. Lead the lost home. Amen.", "Pray for count volunteers this week.", ["PrayerForTheLost", "Shepherd", "Found"]),
]),
("Know Your Rights", ["KnowYourRights"], [
 ("k9", "Service Dog vs ESA vs Pet", "Three categories, three sets of rules.", "Service dogs are task-trained and have public access under the ADA. ESAs provide comfort and have housing protections under the Fair Housing Act. Pets have neither.", "Save this guide.", ["ServiceDog", "EmotionalSupportAnimal", "ADA"]),
 ("k9", "Two Questions Only", "Businesses can only ask TWO questions about a service dog.", "Is the dog required because of a disability? What work or task has it been trained to perform? No certification or vest is required by federal law.", "Share with a business owner.", ["ServiceDogLaw", "ADARules", "TwoQuestions"]),
 ("k9", "ESA Registries Are Scams", "That online ESA certificate? Worthless.", "Online registries and instant certificates have no legal standing. Housing accommodations rely on documentation from a licensed provider who knows you.", "Warn a friend before they waste money.", ["ESAScam", "ConsumerAlert", "FairHousing"]),
 ("resource", "Airlines and ESAs", "Can your ESA fly with you?", "Since 2021, U.S. airlines aren't required to accept ESAs. Trained psychiatric service dogs are accepted, usually with a DOT form.", "Save before your next trip.", ["AirTravel", "PsychiatricServiceDog", "DOTRules"]),
 ("k9", "The Tuck", "Public manners start under the table.", "Teach your dog to lie under your chair, out of the aisle, for a whole meal. Practice at home, then on a pet-friendly patio.", "Show us your dog's best tuck!", ["PublicAccess", "ServiceDogTraining", "Tuck"]),
 ("partner", "Landlords: Let's Talk", "Pet-inclusive housing ends veteran homelessness faster.", "Healthy, trained, documented dogs make great tenants. We help veterans build pet résumés with vaccines, training certificates, and references.", "Landlords: partner with Faith Forward.", ["PetFriendlyLandlords", "Housing", "PetResume"]),
 ("faith", "Saturday Prayer: Justice", "Open thy mouth for the dumb. (Proverbs 31:8)", "Lord, give veterans with disabilities fair treatment, open doors, and understanding neighbors. Give our advocates wisdom and gentleness. Amen.", "Pray for veterans' advocates.", ["Proverbs318", "Advocacy", "JusticePrayer"]),
]),
("Lent for Warriors", ["Lent"], [
 ("faith", "Lent Is Spiritual PT", "Veterans already know what Lent asks.", "Forty days of discipline, stripping away comfort to build something stronger. Not to earn God's love, but to clear what crowds Him out.", "What are you giving up or taking on this Lent?", ["LentenSeason", "SpiritualDiscipline", "40Days"]),
 ("faith", "Ash Wednesday", "Remember that you are dust, and to dust you shall return.", "Ashes are honest: I'm mortal, I fall short, I need God. That honesty is freeing. And Lent ends at an empty tomb.", "Post your ashes selfie and tag #FaithForward.", ["AshWednesday", "Ashes", "Repent"]),
 ("donate", "40 Days, 40 Backpacks", "Our Lenten challenge: one backpack a week.", "Individuals, families, and parishes each pack one backpack per week of Lent for veterans on the street. Fasting + giving = almsgiving.", "Accept the challenge and tag us.", ["40Backpacks", "Almsgiving", "LentChallenge"]),
 ("mental", "Fasting and Recovery", "A Lenten fast can strengthen sobriety.", "Giving up alcohol, energy drinks, or social media for Lent builds self-control. In recovery? Work with your sponsor and doctor.", "Share what you're fasting from.", ["SoberLent", "Recovery", "SelfControl"]),
 ("faith", "The Jesus Prayer", "A one-line prayer you can pray all Lent.", "'Lord Jesus Christ, Son of God, have mercy on me, a sinner.' Pray it morning and night, on walks, on hard days.", "Pray it now with us.", ["JesusPrayer", "LentPrayer", "Mercy"]),
 ("k9", "Dogs Need Fasting Too", "Most pets are overweight.", "Measure meals, count training treats in the daily ration, and aim to feel ribs easily under a thin layer of fat.", "Check your dog's ribs today.", ["DogNutrition", "HealthyWeight", "BodyCondition"]),
 ("faith", "Saturday Prayer: Lent", "Lord, I am dust, and You love me anyway.", "Strip away what keeps me from You. Strengthen my prayer, discipline my appetites, open my hands to the poor. Amen.", "Pray this every Saturday of Lent.", ["LentenPrayer", "Dust", "LoveAnyway"]),
]),
("Love That Stays", ["VeteranFamilies"], [
 ("story", "Valentine's Day for Veteran Families", "Real love looks like 1 Corinthians 13.", "Patient, kind, enduring. The love that holds veteran families together through deployment, injury, and transition.", "Tag the person who's stayed by you.", ["ValentinesDay", "LoveThatStays", "MilitaryLove"]),
 ("mental", "Talk About the Hard Stuff", "A weekly check-in can save a marriage.", "Set a calm time to talk each week. Agree on a code word for 'I need a break.' Learn each other's triggers.", "Try a check-in this week.", ["MarriageTips", "CommunicationMatters", "VeteranMarriage"]),
 ("resource", "Caregiver Support", "Caring for a veteran? You need care too.", "The VA Caregiver Support Line (855-260-3274) helps those caring for veterans. You can't pour from an empty cup.", "Share with a caregiver.", ["CaregiverSupport", "VACaregiver", "SelfCare"]),
 ("faith", "I Will Never Leave Thee", "When human love fails, God's doesn't.", "'I will never leave thee, nor forsake thee' (Hebrews 13:5). That covenant can be the foundation for rebuilding every other one.", "Share with someone who feels abandoned.", ["Hebrews135", "NeverForsaken", "Covenant"]),
 ("k9", "Family Dog Rules", "Everyone in the house should use the same words.", "Write your dog's commands on the fridge: Sit, Down, Place, Here, Leave It, Out, Free. Consistency is love to a dog.", "Post your family's command list!", ["FamilyDog", "Consistency", "DogCommands"]),
 ("donate", "Caregiver Care Packages", "Bless a veteran's caregiver this week.", "Coffee, a gift card, a handwritten note, and a prayer. Caregivers serve too.", "Sponsor a caregiver care package.", ["CareForCaregivers", "Kindness", "MilitarySpouses"]),
 ("faith", "Saturday Prayer: Families", "Holy Family, protect our veteran families.", "Hold together homes strained by deployment, injury, and loss. Give spouses patience, caregivers rest, and children security. Amen.", "Pray for a military family by name.", ["FamilyPrayer", "HolyFamily", "MilitaryFamilies"]),
]),
("VA Field Guide", ["VAHealthcare"], [
 ("resource", "Enroll in VA Healthcare", "Step 1: gather these documents.", "DD-214, photo ID, Social Security number, insurance info, and income info if needed. Apply online at VA.gov, call 877-222-8387, or apply in person.", "Save this checklist.", ["VAEnrollment", "DD214", "VeteranHealthcare"]),
 ("resource", "St. Louis VA Facilities", "Know your VA.", "John J. Cochran VA Medical Center (915 N. Grand), Jefferson Barracks VA (1 Jefferson Barracks Dr), St. Louis Vet Center (4735 Fyler Ave), plus regional clinics.", "Share with a St. Louis veteran.", ["StLouisVA", "JohnCochranVA", "JeffersonBarracks"]),
 ("resource", "Lost Your DD-214?", "How to get a copy of your discharge papers.", "Request records through the National Archives or milConnect, or ask a free Veterans Service Officer to help you.", "Save this for later.", ["DD214Help", "MilitaryRecords", "NationalArchives"]),
 ("resource", "Patient Advocates", "Problem at the VA? Ask for a patient advocate.", "Every VA facility has patient advocates who help resolve problems with care. Write down names, dates, and what was said.", "Share so no veteran gives up.", ["PatientAdvocate", "KnowYourOptions", "VACare"]),
 ("volunteer", "Give a Ride", "Missed appointments often come down to a ride.", "Faith Forward volunteers drive veterans to VA appointments and can watch their dogs while they're inside.", "Sign up as a volunteer driver.", ["VolunteerDriver", "RidesForVets", "ShowUp"]),
 ("faith", "Ask, Seek, Knock", "Sometimes you have to knock more than once.", "Matthew 7:7 is a promise for persistence. Keep knocking. Bring a buddy.", "Comment 'Knock' if you're still knocking.", ["Matthew77", "Persistence", "KeepKnocking"]),
 ("faith", "Saturday Prayer: Patience", "Lord, give patience in the paperwork.", "Give veterans patience with phone trees and forms. Give VA staff compassion. Open doors that seem shut. Amen.", "Pray for VA doctors and nurses this weekend.", ["PrayerForPatience", "VAWorkers", "Paperwork"]),
]),
("Recovery", ["Recovery"], [
 ("faith", "No Pit So Deep", "There is no pit so deep that God's love is not deeper still.", "Betsie ten Boom said it in a concentration camp. Many veterans know the pit of addiction. God's love goes deeper.", "Share with someone in the pit right now.", ["NoPitSoDeep", "Hope", "CorrieTenBoom"]),
 ("mental", "Addiction Is a Disease", "Addiction isn't a moral failure.", "Veterans may use substances to manage pain, sleep, or nightmares. Recovery is possible, and it rarely happens alone.", "Share to end the stigma.", ["AddictionRecovery", "NoShame", "RecoveryIsPossible"]),
 ("resource", "SAMHSA Helpline", "Free, confidential, 24/7: 800-662-4357.", "SAMHSA's National Helpline gives treatment referrals. Veterans can also ask about VA residential programs like SARRTP at Jefferson Barracks.", "Save the number.", ["SAMHSA", "TreatmentHelp", "VASARRTP"]),
 ("mental", "Detox Can Be Dangerous", "Never detox from alcohol alone.", "Withdrawal from alcohol or benzodiazepines can be life-threatening. Get medical supervision.", "Share this. It could save a life.", ["SafeDetox", "AlcoholWithdrawal", "GetHelp"]),
 ("k9", "Dogs and Recovery", "A dog gives your day structure.", "Feeding, walking, and training on a schedule anchor your own routine and add purpose. Many people in recovery credit their dogs.", "Tell us how your dog helps you.", ["RecoveryDog", "Routine", "Purpose"]),
 ("faith", "Relapse Isn't the End", "Peter denied Christ three times, and was restored.", "If you slipped, get back up, call your sponsor, and start again today. Grace is bigger than your relapse.", "Comment 'Day 1' if you're starting again. We're with you.", ["Restored", "StartAgain", "OneDayAtATime"]),
 ("faith", "Saturday Prayer: Sobriety", "One day at a time is all I can carry.", "Keep me sober today and honest today. Surround me with people who tell me the truth. When I fall, lift me without shame. Amen.", "Pray for someone in recovery.", ["RecoveryPrayer", "Serenity", "Sobriety"]),
]),
("Handler First", ["HandlerTraining"], [
 ("k9", "It Travels Down the Leash", "Your stress travels straight down the leash.", "Military working dog handlers know it: your confidence or anxiety flows to the dog. That's why we train the handler first.", "Take 3 deep breaths before your next walk.", ["ItTravelsDownTheLeash", "HandlerFirst", "MWD"]),
 ("k9", "The Timing Drill", "Practice your timing without a dog.", "Have a friend drop a tennis ball and say 'YES' the instant it hits the floor. 20 reps. Get 18/20 on time and your dog will learn faster.", "Film your timing drill and tag us!", ["TimingDrill", "MarkerTraining", "DogTrainerSkills"]),
 ("k9", "Short Sessions Win", "Five minutes beats one hour.", "Two or three 5-minute sessions a day, same words, same signals, ending on success. That's how dogs learn fastest.", "Set a 5-minute timer and train now.", ["ShortSessions", "DogTraining", "Consistency"]),
 ("mental", "Box Breathing", "A breathing drill for handlers and veterans.", "In 4, hold 4, out 4, hold 4. Repeat 4 times. Calm handler, calm dog. It works for PTSD too.", "Try it right now.", ["BoxBreathing", "Calm", "Regulate"]),
 ("k9", "The Faith Forward Markers", "YES. GOOD. UH-UH. FREE.", "YES = reward coming. GOOD = keep going, reward comes to you. UH-UH = try again. FREE = release. Clear language makes a confident dog.", "Save this marker chart.", ["MarkerWords", "ClearCommunication", "PositiveTraining"]),
 ("story", "Gypse's Progress", "Two months in. Here's what Gypse learned.", "Name, focus, sit, down, place, and a growing 'leave it.' Every session is logged in the K9 Suite. Progress you can measure.", "Follow along for her next milestone.", ["GypseUpdate", "TrainingProgress", "PitBullTraining"]),
 ("faith", "Saturday Prayer: Patience", "Teach me patience through this animal.", "Lord, let what I learn on the leash make me a better servant of people. Let my training never be in anger. Amen.", "Pray before your weekend training.", ["PatiencePrayer", "TrainingWithFaith", "GentleLeader"]),
]),
("Women Veterans", ["WomenVeterans"], [
 ("story", "She Served", "Women veterans are veterans. Full stop.", "Women have served in every American war. Too often they're asked if the veteran plates belong to their husband.", "Tag a woman veteran and thank her.", ["SheServed", "WomensHistoryMonth", "WomenWhoServed"]),
 ("resource", "Women Veterans Call Center", "Call or text 855-829-6636.", "The VA Women Veterans Call Center answers questions about benefits and care for women veterans.", "Save and share.", ["WomenVeteransCallCenter", "VABenefits", "HerCare"]),
 ("mental", "MST Care Is Free", "Military sexual trauma care is free at the VA.", "The VA provides free MST-related care, even without a service-connected rating. Every VA has an MST Coordinator.", "Share. Someone needs to know.", ["MST", "Survivors", "YouAreBelieved"]),
 ("faith", "St. Patrick's Day", "Christ with me, Christ before me, Christ behind me.", "St. Patrick was enslaved, escaped, and went back to evangelize the land of his captors. That's redemption. Happy St. Patrick's Day!", "Pray St. Patrick's Breastplate today.", ["StPatricksDay", "Breastplate", "Redemption"]),
 ("donate", "Hygiene for Her", "Feminine products are among the most-needed donations.", "Pads, tampons, wipes, and travel-size hygiene items. Women veterans on the street often go without.", "Donate a pack this month.", ["FeminineHygiene", "PeriodPoverty", "DonateDignity"]),
 ("faith", "St. Joseph, Protector", "On his feast day, ask St. Joseph to protect veteran families.", "Joseph protected Mary and Jesus as refugees. He's patron of families, workers, and a happy death.", "Ask St. Joseph for one intention today.", ["StJoseph", "Protector", "March19"]),
 ("faith", "Saturday Prayer: Women Who Served", "Strength and honour are her clothing.", "Lord, heal wounds no one else knows about. Surround women veterans with safety, dignity, and sisterhood. Amen.", "Pray for a woman veteran by name.", ["Proverbs3125", "WomenVeteransPrayer", "Sisterhood"]),
]),
("Holy Week", ["HolyWeek"], [
 ("faith", "Palm Sunday", "A King on a borrowed donkey.", "Conquerors rode war horses. Jesus rode a donkey. Real strength is power under control.", "Hosanna! Share your palm photo.", ["PalmSunday", "Hosanna", "HumbleKing"]),
 ("faith", "Servant Leadership", "The best leaders eat last.", "Jesus washed His disciples' feet. The best NCOs check on their people and do the dirty jobs alongside them.", "Tag the best leader you ever served with.", ["ServantLeadership", "LeadersEatLast", "WashFeet"]),
 ("faith", "The Fickle Crowd", "Hosanna on Sunday. Crucify on Friday.", "Veterans know the fickleness of public praise. Jesus didn't build His identity on the crowd. Neither should we.", "Share with someone who feels forgotten.", ["Identity", "NotTheCrowd", "WorthInChrist"]),
 ("faith", "Spy Wednesday: Betrayal and Mercy", "Judas sold Him for thirty pieces of silver.", "Many veterans know betrayal by leaders, by institutions, by friends. Jesus knew it too, and He still washed Judas's feet. Bring your betrayal to the One who understands.", "Share with someone carrying a betrayal.", ["SpyWednesday", "Betrayal", "MoralInjury"]),
 ("faith", "Holy Thursday", "He gave us an example.", "Tonight the Church remembers the Last Supper and the washing of feet. Who will you serve this week?", "Find a Holy Thursday service near you.", ["HolyThursday", "LastSupper", "ServeOneAnother"]),
 ("faith", "Good Friday", "With his stripes we are healed. (Isaiah 53:5)", "Today we remember the Cross. He was wounded for our transgressions. Every wound we carry, He carried first.", "Pause at 3 p.m. to pray.", ["GoodFriday", "TheCross", "Isaiah535"]),
 ("faith", "Holy Saturday & the Easter Vigil", "The silence before the victory.", "Holy Saturday is for everyone waiting in grief. The tomb is sealed. Tonight the Easter Vigil begins in darkness with a single flame, like the flame on our crest that no darkness can put out.", "Pray for everyone in a Holy Saturday season.", ["HolySaturday", "EasterVigil", "LightOfChrist"]),
]),
("Easter Week", ["Easter"], [
 ("faith", "He Is Risen", "Christ is risen! He is risen indeed!", "Nothing (not war, not addiction, not homelessness, not despair) gets the final word. That's Spiritus Invictus.", "Comment 'He is risen indeed!'", ["HeIsRisen", "EasterSunday", "Resurrection"]),
 ("story", "Small Resurrections", "We see resurrections every week.", "A veteran gets keys to an apartment, with his dog. A man sober one day becomes sober one year. A woman who hasn't prayed since Iraq picks up a rosary.", "Share a resurrection story from your life.", ["Resurrection", "Transformation", "Hope"]),
 ("faith", "He Kept His Scars", "The risen Christ kept His wounds.", "He invited Thomas to touch them. Scars aren't shameful; they're proof of love and survival.", "Share with a veteran who carries scars.", ["Scars", "DoubtingThomas", "WoundedHealer"]),
 ("k9", "Spring Health Check", "Spring is here. Is your dog protected?", "Restart heartworm and flea/tick prevention (year-round is best in Missouri) and schedule annual vaccines and an exam.", "Book your dog's checkup this month.", ["SpringPetCare", "Heartworm", "FleaAndTick"]),
 ("mental", "Holidays and Grief", "Easter can be hard if you're grieving.", "Holidays can bring grief to the surface. If today is heavy, call 988 and press 1, or reach out to us.", "Check on someone today.", ["GriefSupport", "Easter", "988"]),
 ("volunteer", "Easter People", "We are the Easter people and hallelujah is our song.", "Live like it this week: visit someone who feels entombed, bring hope, roll away a stone.", "Tell us how you'll bring hope this week.", ["EasterPeople", "Hallelujah", "BringHope"]),
 ("faith", "Saturday Prayer: Raise Us Up", "Risen Lord, raise every veteran who feels buried.", "Raise those buried by grief, addiction, homelessness, or despair. Fill us with the unconquered Spirit. Amen.", "Pray this with us.", ["EasterPrayer", "RaiseUs", "UnconqueredSpirit"]),
]),
("Housing First", ["HousingFirst"], [
 ("resource", "What Is Housing First?", "Stability first. Everything else follows.", "Housing First helps people into permanent housing without requiring them to 'get ready' first. It's hard to stay sober or keep appointments while sleeping outside.", "Share to spread understanding.", ["HousingFirst", "EndHomelessness", "Stability"]),
 ("resource", "SSVF", "Supportive Services for Veteran Families.", "SSVF provides rapid re-housing and homelessness prevention, including help with deposits and rent. In St. Louis, contact St. Patrick Center (314-802-0700).", "Save and share.", ["SSVF", "RapidRehousing", "StPatrickCenter"]),
 ("donate", "Welcome-Home Kits", "Walls aren't a home. Welcome is.", "Dishes, sheets, towels, cleaning supplies, a Bible, and dog bowls for veterans moving into their first apartment.", "Assemble a welcome-home kit.", ["WelcomeHome", "HousewarmingForVets", "NewBeginnings"]),
 ("k9", "The Pet Résumé", "Landlords love a pet résumé.", "Vaccine records, spay/neuter proof, training certificates like CGC, a vet or trainer reference, and a photo of your calm dog.", "Save this list.", ["PetResume", "RentingWithDogs", "CanineGoodCitizen"]),
 ("faith", "Except the Lord Build the House", "Psalm 127:1", "Housing solves homelessness. It doesn't automatically solve loneliness. The Church completes the picture with visits, fellowship, and blessing.", "Bless a home this week.", ["Psalm1271", "HouseBlessing", "Community"]),
 ("partner", "Landlords and Property Managers", "Help end veteran homelessness from your rental office.", "Partner with VA and SSVF programs, accept vouchers, and consider pet-inclusive policies for veterans with trained dogs.", "Landlords: message us.", ["LandlordPartners", "AcceptVouchers", "HousingPartners"]),
 ("faith", "Saturday Prayer: A Place", "Lord, You prepare a place for us.", "Prepare homes for every veteran still outside. Move landlords, agencies, and churches to make room for veterans and their animals. Amen.", "Pray for a veteran waiting on housing.", ["HousingPrayer", "John142", "MakeRoom"]),
]),
("Healthy Dogs", ["DogHealth"], [
 ("k9", "How Much Should You Feed?", "The bag usually overestimates.", "Vets estimate calories from body weight and activity. Our K9 Suite calculates it for you. Then adjust 10% every two weeks to keep ribs easy to feel.", "Try the calculator. Link in bio.", ["DogNutrition", "FeedingGuide", "HealthyDog"]),
 ("k9", "Budget Feeding Tips", "Feed a dog well on a tight budget.", "Buy the largest bag you can store, pick a mid-range food with named protein first, and use part of the daily ration as training treats.", "Share your best budget tip.", ["BudgetDogFood", "SaveMoney", "SmartFeeding"]),
 ("k9", "Never Feed These", "Xylitol can kill a dog.", "Xylitol, chocolate, grapes, raisins, onions, garlic, cooked bones, fatty scraps, and human medications. ASPCA Poison Control: (888) 426-4435.", "Save this list.", ["ToxicFoods", "Xylitol", "PetPoison"]),
 ("k9", "Core Vaccines", "Which vaccines does your dog need?", "Core: rabies and DAPP. For outdoor dogs in Missouri, leptospirosis is strongly recommended. Ask your vet about bordetella, flu, and Lyme.", "Book your vaccine appointment.", ["DogVaccines", "Rabies", "Leptospirosis"]),
 ("k9", "Bloat Is an Emergency", "German Shepherd owner? Know this.", "Retching with nothing coming up, a swollen belly, and restlessness can be bloat (GDV). Go to an emergency vet immediately.", "Share with every big-dog owner.", ["Bloat", "GDV", "GermanShepherd"]),
 ("donate", "Prevention Saves Lives", "Flea, tick, and heartworm prevention for veterans' dogs.", "Prevention is far cheaper than treatment. Donations of preventives help us keep veterans' dogs healthy year-round.", "Donate preventives or sponsor a clinic.", ["PetPrevention", "VeteransDogs", "SponsorAClinic"]),
 ("faith", "Saturday Prayer: For Sick Animals", "Lord, my dog is hurting.", "Guide the vet's hands. Ease the pain. If it's time to let go, give me courage to choose mercy. Amen.", "Pray for someone's sick pet today.", ["PetPrayer", "Mercy", "Veterinarians"]),
]),
("Be There", ["BeThere"], [
 ("mental", "Ask. Care. Escort.", "You don't have to be a professional to save a life.", "Ask directly about suicide. Care: listen without judging. Escort: connect them to help. Call 988 and press 1 together.", "Learn ACE and share it.", ["ACE", "SuicidePrevention", "BeThere"]),
 ("mental", "Asking Doesn't Plant the Idea", "It's okay to ask: are you thinking about killing yourself?", "Asking directly often brings relief: someone finally noticed. It does not put the idea in their head.", "Share to bust the myth.", ["AskDirectly", "MythBusting", "SuicideAwareness"]),
 ("mental", "Warning Signs", "Know the warning signs.", "Talking about being a burden, giving things away, withdrawing, increased drinking, reckless behavior, sudden calm after depression.", "Save this.", ["WarningSigns", "KnowTheSigns", "PreventSuicide"]),
 ("mental", "Time and Distance", "Lethal means safety saves lives.", "Putting time and distance between someone in crisis and firearms or medications saves lives. Ask a trusted friend to hold them during a hard season.", "Share with a gun owner you love.", ["LethalMeansSafety", "SecureStorage", "SaveALife"]),
 ("faith", "Hope Thou in God", "Why art thou cast down, O my soul? (Psalm 42:11)", "The psalmist argued with his own despair. Borrow his hope today. You're not a burden. Your story isn't over.", "Share with someone who's downcast.", ["Psalm42", "HopeInGod", "YouMatter"]),
 ("k9", "A Reason to Stay", "Many veterans say their dog kept them alive.", "Someone depends on them. If you're worried about a veteran with a dog, ask about the dog. It can open a door to a deeper conversation.", "Tell us how your dog has helped you.", ["DogsSaveLives", "ReasonToStay", "VeteranAndDog"]),
 ("faith", "Saturday Prayer: Life", "God of life, hold back every veteran at the edge.", "Speak to them: stay, you are needed, you are loved. Give us courage to ask and stay with the answer. Amen.", "Text a veteran today.", ["PrayerForLife", "Stay", "YouAreLoved"]),
]),
("Join the Mission", ["JoinTheMission"], [
 ("volunteer", "Here Am I, Send Me", "You don't need special skills. Just a willing heart and good shoes.", "Outreach, sorting, driving, prayer team, K9, events, and professional skills. Faith Forward has a place for you.", "Sign up on our website.", ["HereAmISendMe", "Isaiah68", "Volunteer"]),
 ("partner", "Mental Health Providers", "Clinicians: let's link veterans to care together.", "We provide warm handoffs, transportation, dog care during appointments, and follow-up. You provide care. Let's sign an MOU.", "Message us to partner.", ["MentalHealthProviders", "Partnership", "VeteranCare"]),
 ("partner", "Parishes and Churches", "Host a drive. Bless supplies. Open a warming space.", "Churches multiply our impact with volunteers, donations, prayer, and sacraments.", "Tag your parish.", ["ParishPartners", "ChurchOutreach", "FaithInAction"]),
 ("partner", "Veterinarians", "Help keep veterans and their dogs together.", "Vaccine clinics, spay/neuter, emergency care, and discounted services for veterans' dogs.", "Vets: partner with our K9 program.", ["VeterinaryPartners", "VetClinic", "K9Program"]),
 ("mission", "Six Months of Faith Forward", "Look what God has done in six months.", "Blessed backpacks, warm socks, fed dogs, answered prayers, new partners, and veterans walked home. Thank you for being part of it.", "Share your favorite Faith Forward moment.", ["SixMonths", "Gratitude", "Impact"]),
 ("story", "The Mission Continues", "Every veteran we met was wounded. None were conquered.", "That's the promise of our crest and the Gospel. Spiritus Invictus. The mission continues.", "Follow, share, and join us for the next six months.", ["MissionContinues", "SpiritusInvictus", "FaithForward"]),
 ("faith", "Saturday Prayer: Commissioning", "Lord, send us.", "You call us from the streets to send us back into them. Commission us as ambassadors of Your mercy. Here am I, Lord. Send me. Amen.", "Pray this and then go serve.", ["Commissioning", "SendMe", "Mission"]),
]),
]
